prs.body:
Closes #63800

The second commit moves types for our VS Code extension API into the typescript package, generating a big chunk of the language server protocol, since middleware registration exposes it.

Example usage:

```ts
import * as vscode from "vscode";
import type { ExtensionAPI } from "typescript/unstable/vscode";

export async function activate(context: vscode.ExtensionContext) {
    const extension = vscode.extensions.getExtension<ExtensionAPI>(
        "TypeScriptTeam.native-preview",
    );
    if (!extension) return;

    const extensionAPI = await extension.activate();
    context.subscriptions.push(
        extensionAPI.registerLspMiddleware("textDocument/hover", (hover, context) => {
            if (!hover || !context.params.textDocument.uri.endsWith(".vue")) {
                return hover;
            }
            return {
                ...hover,
                contents: { kind: "markdown", value: "Custom hover for Vue files" },
            };
        }),
    );
}
```
